// The conformance runner checks this implementation against the committed
// vectors in contracts/format/v3/vectors/.
//
// For Go this is a regression guard rather than an independent check: the
// vectors are generated by cmd/mkvectors, which uses this package. Its value is
// that any change to the format code makes the committed vectors fail, forcing
// a deliberate regeneration and a visible diff instead of a silent format
// change. The same runner shape is what the C and Rust implementations must
// satisfy, where the check is genuinely independent.

// The vectors live in the Cairn contracts, not in this repository: see
// internal/contracts for how they are found (CAIRN_CONTRACTS, or a fetched copy).
var vectorDir = contracts.Vectors("format", "v3")

// vectorKeys is the provider a conformance verifier is given: K_root version 1,
// read from keys.json. They are public test keys.
func vectorKeys(t *testing.T) *RootKeyProvider {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(vectorDir, "keys.json"))
	if err != nil {
		t.Fatalf("read keys.json: %v", err)
	}
	var k struct {
		RootKeyHex string `json:"root_key_hex"`
		Version    uint32 `json:"storage_key_version"`
	}
	if err := json.Unmarshal(raw, &k); err != nil {
		t.Fatalf("parse keys.json: %v", err)
	}
	root, err := hex.DecodeString(k.RootKeyHex)
	if err != nil || len(root) != RootKeySize {
		t.Fatalf("keys.json root_key_hex is not %d bytes", RootKeySize)
	}
	p := &RootKeyProvider{Version: k.Version}
	copy(p.Root[:], root)
	return p
}

// keyedVerdict is the expected outcome of scanning with the vector key.
type keyedVerdict struct {
	Error              string `json:"error"`
	SegmentKeyHex      string `json:"segment_key_hex"`
	StopReason         string `json:"stop_reason"`
	FramesRetained     *int   `json:"frames_retained"`
	StopOffset         *int   `json:"stop_offset"`
	PlaintextSHA256Hex string `json:"plaintext_sha256_hex"`
}

// checkKeyed scans b with the vector key and compares against the verdict.
//
// It also re-derives the segment key independently of the scanner and compares
// it with the committed one, so a KDF regression is reported as that rather than
// as a puzzling tag failure.
func checkKeyed(t *testing.T, b []byte, state ScanState, want *keyedVerdict) {
	t.Helper()

	res, err := ScanSegment(b, state, vectorKeys(t))
	if want.Error != "" {
		var got string
		switch {
		case errors.Is(err, ErrKeyVersionMismatch):
			got = "KEY_VERSION_MISMATCH"
		case errors.Is(err, ErrNoKey):
			got = "NO_KEY"
		}
		if got != want.Error {
			t.Errorf("keyed scan error = %v, want %s", err, want.Error)
		}
		return
	}
	if err != nil {
		t.Fatalf("keyed ScanSegment: %v", err)
	}

	k, err := DeriveSegmentKey(vectorKeys(t).Root, &res.Header)
	if err != nil {
		t.Fatalf("DeriveSegmentKey: %v", err)
	}
	if got := hex.EncodeToString(k[:]); got != want.SegmentKeyHex {
		t.Errorf("segment key = %s, want %s — HKDF derivation differs from the vector", got, want.SegmentKeyHex)
	}

	if got := res.Stop.String(); got != want.StopReason {
		t.Errorf("keyed stop_reason = %q, want %q (%s)", got, want.StopReason, res.StopDetail)
	}
	if want.FramesRetained != nil && len(res.Frames) != *want.FramesRetained {
		t.Errorf("keyed frames_retained = %d, want %d", len(res.Frames), *want.FramesRetained)
	}
	if want.StopOffset != nil && res.StopOffset != *want.StopOffset {
		t.Errorf("keyed stop_offset = %d, want %d", res.StopOffset, *want.StopOffset)
	}

	h := sha256.New()
	for i := range res.Frames {
		var l [4]byte
		binary.LittleEndian.PutUint32(l[:], uint32(len(res.Frames[i].Payload)))
		h.Write(l[:])
		h.Write(res.Frames[i].Payload)
	}
	if got := hex.EncodeToString(h.Sum(nil)); got != want.PlaintextSHA256Hex {
		t.Errorf("plaintext digest = %s, want %s", got, want.PlaintextSHA256Hex)
	}
}

// checkMultiSegmentVector scans segment-N.bin in order, threading state, in both
// modes, and confirms that segment 1 from the zero state breaks the chain.
func checkMultiSegmentVector(t *testing.T, dir string, raw []byte) {
	t.Helper()

	var exp struct {
		Segments []struct {
			StopReason     string `json:"stop_reason"`
			FramesRetained int    `json:"frames_retained"`
			StopOffset     int    `json:"stop_offset"`
		} `json:"segments"`
		Keyed         []keyedVerdict `json:"keyed"`
		FromZeroState struct {
			StopReason string `json:"stop_reason"`
		} `json:"segment_1_from_zero_state"`
	}
	if err := json.Unmarshal(raw, &exp); err != nil {
		t.Fatalf("parse expected.json: %v", err)
	}

	var segs [][]byte
	for i := range exp.Segments {
		b, err := os.ReadFile(filepath.Join(dir, fmt.Sprintf("segment-%d.bin", i)))
		if err != nil {
			t.Fatal(err)
		}
		segs = append(segs, b)
	}

	for _, keyed := range []bool{false, true} {
		var keys KeyProvider
		if keyed {
			keys = vectorKeys(t)
		}
		var state ScanState
		for i, b := range segs {
			res, err := ScanSegment(b, state, keys)
			if err != nil {
				t.Fatalf("segment %d (keyed=%v): %v", i, keyed, err)
			}
			if got := res.Stop.String(); got != exp.Segments[i].StopReason {
				t.Errorf("segment %d (keyed=%v): stop_reason = %q, want %q", i, keyed, got, exp.Segments[i].StopReason)
			}
			if len(res.Frames) != exp.Segments[i].FramesRetained || res.StopOffset != exp.Segments[i].StopOffset {
				t.Errorf("segment %d (keyed=%v): %d frames to offset %d, want %d to %d", i, keyed,
					len(res.Frames), res.StopOffset, exp.Segments[i].FramesRetained, exp.Segments[i].StopOffset)
			}
			state = res.Next
		}
	}

	state := ScanState{}
	for i, b := range segs {
		checkKeyed(t, b, state, &exp.Keyed[i])
		res, _ := ScanSegment(b, state, nil)
		state = res.Next
	}

	res, err := ScanSegment(segs[1], ScanState{}, nil)
	if err != nil {
		t.Fatal(err)
	}
	if got := res.Stop.String(); got != exp.FromZeroState.StopReason {
		t.Errorf("segment 1 from the zero state: stop_reason = %q, want %q", got, exp.FromZeroState.StopReason)
	}
}

// checkBindingVector verifies the member segments in the vector directory
// against its manifest.
func checkBindingVector(t *testing.T, dir string, exp *vectorExpectation) {
	t.Helper()

	encoded, err := os.ReadFile(filepath.Join(dir, "manifest.cbor"))
	if err != nil {
		t.Fatal(err)
	}
	m, err := ParseManifest(encoded)
	if err != nil {
		t.Fatalf("ParseManifest: %v", err)
	}

	members := map[string][]byte{}
	for _, mem := range m.Members {
		b, err := os.ReadFile(filepath.Join(dir, mem.Name))
		if err != nil {
			t.Fatalf("read member %s: %v", mem.Name, err)
		}
		if sha256.Sum256(b) != mem.SHA256 || uint64(len(b)) != mem.Length {
			t.Fatalf("member %s does not match its manifest digest: the vector is internally inconsistent", mem.Name)
		}
		members[mem.Name] = b
	}

	err = VerifyMembersAgainstManifest(m, members)
	switch {
	case exp.Binding.Match && err != nil:
		t.Errorf("members should match the manifest: %v", err)
	case !exp.Binding.Match && !errors.Is(err, ErrManifestBindingMismatch):
		t.Errorf("members verified (%v), but the vector expects a binding mismatch", err)
	case !exp.Binding.Match && !strings.Contains(err.Error(), exp.Binding.Field):
		t.Errorf("mismatch reported as %q, want it to name %s", err, exp.Binding.Field)
	}
}

type vectorExpectation struct {
	Name        string `json:"name"`
	Description string `json:"description"`

	Scan *struct {
		StopReason         string         `json:"stop_reason"`
		FramesRetained     int            `json:"frames_retained"`
		StopOffset         int            `json:"stop_offset"`
		DiscardedTailBytes uint32         `json:"discarded_tail_bytes"`
		UnknownTypeCount   int            `json:"unknown_type_count"`
		RecordCounts       map[string]int `json:"record_counts"`
		FirstSeq           *uint32        `json:"first_seq"`
		LastSeq            *uint32        `json:"last_seq"`
	} `json:"scan"`

	Keyed *keyedVerdict `json:"keyed"`

	Binding *struct {
		Match bool   `json:"match"`
		Field string `json:"mismatched_field"`
	} `json:"binding"`

	Header *struct {
		ParseError string `json:"parse_error"`
	} `json:"header"`

	Manifest *struct {
		Valid              bool   `json:"valid"`
		SignatureValid     bool   `json:"signature_valid"`
		ContentRootHex     string `json:"content_root_hex"`
		DevicePublicKeyHex string `json:"device_public_key_hex"`
		CanonicalBytesHex  string `json:"canonical_bytes_sha256_hex"`
	} `json:"manifest"`

	Receipt *struct {
		SignatureValid     bool   `json:"signature_valid"`
		Acknowledges       bool   `json:"acknowledges_uploaded_root"`
		UploadedRootHex    string `json:"uploaded_content_root_hex"`
		ReceiptRootHex     string `json:"receipt_content_root_hex"`
		ServerPublicKeyHex string `json:"server_public_key_hex"`
	} `json:"receipt"`

	Merkle *struct {
		RootHex string   `json:"root_hex"`
		Leaves  []string `json:"leaves_hex"`
	} `json:"merkle"`

	Policy *PolicySnapshot `json:"policy"`

	Events *struct {
		Events []struct {
			EventType     uint8  `json:"event_type"`
			EventTypeName string `json:"event_type_name"`
			LatE7         int32  `json:"lat_e7"`
			LonE7         int32  `json:"lon_e7"`
			Detail        string `json:"detail"`
		} `json:"events"`
	} `json:"events"`

	Health *struct {
		Records []struct {
			HealthState uint8    `json:"health_state"`
			Names       []string `json:"names"`
		} `json:"records"`
	} `json:"health"`

	Update *struct {
		SignatureValid     bool   `json:"signature_valid"`
		FirmwareVersion    string `json:"firmware_version"`
		MinFirmwareVersion string `json:"min_firmware_version"`
		ImageSHA256Hex     string `json:"image_sha256_hex"`
		ImageLength        uint32 `json:"image_length"`
		UpdateKeyHex       string `json:"update_public_key_hex"`
	} `json:"update"`

	OBDExt *struct {
		Records []struct {
			MAPkPa           *uint16  `json:"map_kpa"`
			MAFcgps          *uint16  `json:"maf_cgps"`
			LambdaE4         *uint16  `json:"lambda_e4"`
			AbsLoadRaw       *uint16  `json:"abs_load_raw"`
			BaroKPa          *uint8   `json:"baro_kpa"`
			AmbientTempC     *int8    `json:"ambient_temp_c"`
			FuelTrimShortPct *int8    `json:"fuel_trim_short_pct"`
			FuelTrimLongPct  *int8    `json:"fuel_trim_long_pct"`
			PIDsRequested    uint32   `json:"pids_requested"`
			PIDsAnswered     uint32   `json:"pids_answered"`
			PollCadenceMS    uint16   `json:"poll_cadence_ms"`
			MAPSaturated     bool     `json:"map_saturated"`
			BoostPSI         *float64 `json:"boost_psi"`
			Lambda           *float64 `json:"lambda"`
			AbsLoadPct       *float64 `json:"abs_load_pct"`
		} `json:"records"`
	} `json:"obd_ext"`
}

func TestConformanceVectors(t *testing.T) {
	entries, err := os.ReadDir(vectorDir)
	if err != nil {
		t.Skipf("vectors not generated (%v); run: go run ./cmd/mkvectors", err)
	}

	checked := 0
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}

		dir := filepath.Join(vectorDir, e.Name())
		raw, err := os.ReadFile(filepath.Join(dir, "expected.json"))
		if err != nil {
			t.Errorf("%s: no expected.json: %v", e.Name(), err)
			continue
		}

		// Multi-segment vectors have a different shape.
		var multi struct {
			Segments []json.RawMessage `json:"segments"`
		}
		if json.Unmarshal(raw, &multi) == nil && multi.Segments != nil {
			t.Run(e.Name(), func(t *testing.T) { checkMultiSegmentVector(t, dir, raw) })
			checked++
			continue
		}

		var exp vectorExpectation
		if err := json.Unmarshal(raw, &exp); err != nil {
			t.Errorf("%s: expected.json does not parse: %v", e.Name(), err)
			continue
		}

		t.Run(e.Name(), func(t *testing.T) {
			switch {
			case exp.Events != nil, exp.Health != nil, exp.OBDExt != nil:
				checkScanVector(t, dir, &exp)
				if exp.Events != nil {
					checkEventsVector(t, dir, &exp)
				}
				if exp.Health != nil {
					checkHealthVector(t, dir, &exp)
				}
				if exp.OBDExt != nil {
					checkOBDExtVector(t, dir, &exp)
				}
			case exp.Scan != nil:
				checkScanVector(t, dir, &exp)
			case exp.Header != nil:
				checkHeaderVector(t, dir)
			case exp.Manifest != nil:
				checkManifestVector(t, dir, &exp)
				if exp.Binding != nil {
					checkBindingVector(t, dir, &exp)
				}
			case exp.Receipt != nil:
				checkReceiptVector(t, dir, &exp)
			case exp.Merkle != nil:
				checkMerkleVector(t, &exp)
			case exp.Policy != nil:
				checkPolicyVector(t, dir, &exp)
			case exp.Update != nil:
				checkUpdateVector(t, dir, &exp)
			default:
				t.Skip("no checkable expectation")
			}
		})
		checked++
	}

	if checked == 0 {
		t.Error("no vectors were checked")
	}
	t.Logf("checked %d vectors", checked)
}

func checkScanVector(t *testing.T, dir string, exp *vectorExpectation) {
	t.Helper()

	b, err := os.ReadFile(filepath.Join(dir, "segment.bin"))
	if err != nil {
		t.Fatalf("read segment.bin: %v", err)
	}

	// The structural verdict: no key.
	res, err := ScanSegment(b, ScanState{}, nil)
	if err != nil {
		t.Fatalf("ScanSegment: %v", err)
	}
	for i := range res.Frames {
		if res.Frames[i].Decrypted || res.Frames[i].Payload != nil {
			t.Fatalf("frame %d of a keyless scan exposes a payload", i)
		}
	}

	if exp.Keyed != nil {
		defer checkKeyed(t, b, ScanState{}, exp.Keyed)
	}

	if got := res.Stop.String(); got != exp.Scan.StopReason {
		t.Errorf("stop_reason = %q, want %q (%s)", got, exp.Scan.StopReason, res.StopDetail)
	}
	if len(res.Frames) != exp.Scan.FramesRetained {
		t.Errorf("frames_retained = %d, want %d", len(res.Frames), exp.Scan.FramesRetained)
	}
	if res.StopOffset != exp.Scan.StopOffset {
		t.Errorf("stop_offset = %d, want %d", res.StopOffset, exp.Scan.StopOffset)
	}
	if res.DiscardedTailBytes != exp.Scan.DiscardedTailBytes {
		t.Errorf("discarded_tail_bytes = %d, want %d", res.DiscardedTailBytes, exp.Scan.DiscardedTailBytes)
	}
	if res.UnknownTypeCount != exp.Scan.UnknownTypeCount {
		t.Errorf("unknown_type_count = %d, want %d", res.UnknownTypeCount, exp.Scan.UnknownTypeCount)
	}

	for name, want := range exp.Scan.RecordCounts {
		found := 0
		for rt, n := range res.RecordCounts {
			if rt.String() == name {
				found = n
			}
		}
		if found != want {
			t.Errorf("record_counts[%s] = %d, want %d", name, found, want)
		}
	}

	if exp.Scan.FirstSeq != nil {
		if len(res.Frames) == 0 {
			t.Error("expected frames, got none")
		} else if res.Frames[0].Seq != *exp.Scan.FirstSeq {
			t.Errorf("first_seq = %d, want %d", res.Frames[0].Seq, *exp.Scan.FirstSeq)
		}
	}
	if exp.Scan.LastSeq != nil && len(res.Frames) > 0 {
		if got := res.Frames[len(res.Frames)-1].Seq; got != *exp.Scan.LastSeq {
			t.Errorf("last_seq = %d, want %d", got, *exp.Scan.LastSeq)
		}
	}
}

func checkHeaderVector(t *testing.T, dir string) {
	t.Helper()

	b, err := os.ReadFile(filepath.Join(dir, "segment.bin"))
	if err != nil {
		t.Fatalf("read segment.bin: %v", err)
	}

	if _, err := ScanSegment(b, ScanState{}, nil); err == nil {
		t.Error("expected a header parse error, got none")
	}
}

func checkManifestVector(t *testing.T, dir string, exp *vectorExpectation) {
	t.Helper()

	encoded, err := os.ReadFile(filepath.Join(dir, "manifest.cbor"))
	if err != nil {
		t.Fatalf("read manifest.cbor: %v", err)
	}
	sig, err := os.ReadFile(filepath.Join(dir, "manifest.sig"))
	if err != nil {
		t.Fatalf("read manifest.sig: %v", err)
	}
	pub, err := hex.DecodeString(exp.Manifest.DevicePublicKeyHex)
	if err != nil {
		t.Fatalf("decode device public key: %v", err)
	}

	// The manifest bytes must parse as canonical regardless of signature
	// validity: a bad signature does not make the encoding malformed.
	m, parseErr := ParseManifest(encoded)
	if exp.Manifest.Valid && parseErr != nil {
		t.Fatalf("ParseManifest: %v", parseErr)
	}

	_, verifyErr := VerifyManifest(encoded, sig, ed25519.PublicKey(pub))
	if exp.Manifest.SignatureValid && verifyErr != nil {
		t.Errorf("signature should verify: %v", verifyErr)
	}
	if !exp.Manifest.SignatureValid && verifyErr == nil {
		t.Error("signature verified but the vector expects it to fail")
	}

	if m == nil {
		return
	}

	wantRoot, err := hex.DecodeString(exp.Manifest.ContentRootHex)
	if err != nil {
		t.Fatalf("decode content root: %v", err)
	}
	if string(m.ContentRoot[:]) != string(wantRoot) {
		t.Errorf("content_root = %x, want %x", m.ContentRoot, wantRoot)
	}
	if err := m.VerifyContentRoot(); err != nil {
		t.Errorf("VerifyContentRoot: %v", err)
	}

	// Re-encoding must reproduce the committed bytes exactly. This is the
	// check that catches an accidental encoding change.
	if exp.Manifest.CanonicalBytesHex != "" {
		reencoded, err := m.MarshalCBOR()
		if err != nil {
			t.Fatalf("MarshalCBOR: %v", err)
		}
		digest := sha256.Sum256(reencoded)
		if hex.EncodeToString(digest[:]) != exp.Manifest.CanonicalBytesHex {
			t.Errorf("re-encoded manifest digest = %x, want %s — the encoding changed; "+
				"regenerate the vectors deliberately if this is intended",
				digest, exp.Manifest.CanonicalBytesHex)
		}
	}
}

func checkReceiptVector(t *testing.T, dir string, exp *vectorExpectation) {
	t.Helper()

	encoded, err := os.ReadFile(filepath.Join(dir, "receipt.cbor"))
	if err != nil {
		t.Fatalf("read receipt.cbor: %v", err)
	}
	pub, err := hex.DecodeString(exp.Receipt.ServerPublicKeyHex)
	if err != nil {
		t.Fatalf("decode server public key: %v", err)
	}

	r, err := ParseReceipt(encoded)
	if err != nil {
		t.Fatalf("ParseReceipt: %v", err)
	}

	sigErr := r.Verify(ed25519.PublicKey(pub))
	if exp.Receipt.SignatureValid && sigErr != nil {
		t.Errorf("signature should verify: %v", sigErr)
	}
	if !exp.Receipt.SignatureValid && sigErr == nil {
		t.Error("signature verified but the vector expects it to fail")
	}

	uploaded, err := hex.DecodeString(exp.Receipt.UploadedRootHex)
	if err != nil {
		t.Fatalf("decode uploaded root: %v", err)
	}
	var uploadedRoot [32]byte
	copy(uploadedRoot[:], uploaded)

	ackErr := r.VerifyAcknowledges(ed25519.PublicKey(pub), uploadedRoot)
	if exp.Receipt.Acknowledges && ackErr != nil {
		t.Errorf("receipt should acknowledge the upload: %v", ackErr)
	}
	if !exp.Receipt.Acknowledges && ackErr == nil {
		t.Error("receipt accepted as an acknowledgement but the vector expects rejection")
	}
}

func checkMerkleVector(t *testing.T, exp *vectorExpectation) {
	t.Helper()

	// Leaves present: check the tree construction directly.
	if exp.Merkle.Leaves != nil {
		leaves := make([][32]byte, 0, len(exp.Merkle.Leaves))
		for _, h := range exp.Merkle.Leaves {
			b, err := hex.DecodeString(h)
			if err != nil {
				t.Fatalf("decode leaf: %v", err)
			}
			var l [32]byte
			copy(l[:], b)
			leaves = append(leaves, l)
		}

		root := MerkleRoot(leaves)
		if hex.EncodeToString(root[:]) != exp.Merkle.RootHex {
			t.Errorf("root = %x, want %s", root, exp.Merkle.RootHex)
		}
		return
	}

	// Otherwise it is a content-root vector described by members.json.
	t.Skip("content root checked via members.json in TestContentRootIsOrderIndependent")
}

// checkPolicyVector verifies the committed payload decodes to the expected
// values *and* re-encodes to the same bytes.
//
// The re-encode is the point. Two bundles captured under identical policy must
// have byte-identical snapshots, which is what lets a reader group them without
// trusting the version number — and only a committed payload can demonstrate
// that across implementations.
func checkPolicyVector(t *testing.T, dir string, exp *vectorExpectation) {
	raw, err := os.ReadFile(filepath.Join(dir, "policy.cbor"))
	if err != nil {
		t.Fatalf("read policy.cbor: %v", err)
	}

	got, err := ParsePolicySnapshot(raw)
	if err != nil {
		t.Fatalf("ParsePolicySnapshot: %v", err)
	}

	if *got != *exp.Policy {
		t.Errorf("decoded policy does not match the expectation\n got: %+v\nwant: %+v",
			*got, *exp.Policy)
	}

	reencoded, err := got.MarshalCBOR()
	if err != nil {
		t.Fatalf("MarshalCBOR: %v", err)
	}
	if !bytes.Equal(reencoded, raw) {
		t.Errorf("re-encoding produced %d bytes, want the committed %d — this "+
			"implementation does not produce byte-identical output",
			len(reencoded), len(raw))
	}
}

// checkEventsVector walks the segment and checks every trip event, including
// the unknown type that must be named rather than discarded.
func checkEventsVector(t *testing.T, dir string, exp *vectorExpectation) {
	b, err := os.ReadFile(filepath.Join(dir, "segment.bin"))
	if err != nil {
		t.Fatalf("read segment.bin: %v", err)
	}

	res, err := ScanSegment(b, ScanState{}, vectorKeys(t))
	if err != nil {
		t.Fatalf("ScanSegment: %v", err)
	}

	var seen int
	for i := range res.Frames {
		f := &res.Frames[i]
		if f.RecordType != RecordTripEvent {
			continue
		}
		if seen >= len(exp.Events.Events) {
			t.Fatalf("segment holds more events than the expectation names")
		}
		want := exp.Events.Events[seen]
		seen++

		e, err := ParseTripEvent(f.Payload)
		if err != nil {
			t.Errorf("event %d does not parse: %v", seen-1, err)
			continue
		}

		if e.EventType != want.EventType {
			t.Errorf("event %d type = %d, want %d", seen-1, e.EventType, want.EventType)
		}
		if name := EventTypeName(e.EventType); name != want.EventTypeName {
			t.Errorf("event %d name = %q, want %q", seen-1, name, want.EventTypeName)
		}
		if e.LatE7 != want.LatE7 || e.LonE7 != want.LonE7 {
			t.Errorf("event %d position = (%d, %d), want (%d, %d)", seen-1,
				e.LatE7, e.LonE7, want.LatE7, want.LonE7)
		}
		if e.Detail != want.Detail {
			t.Errorf("event %d detail = %q, want %q", seen-1, e.Detail, want.Detail)
		}

		// Re-encoding must reproduce the payload, or an implementation could
		// read these records and not write them.
		reencoded, err := EncodeTripEvent(e.EventType, e.LatE7, e.LonE7, e.Detail)
		if err != nil {
			t.Errorf("event %d will not re-encode: %v", seen-1, err)
		} else if !bytes.Equal(reencoded, f.Payload) {
			t.Errorf("event %d re-encodes to different bytes", seen-1)
		}
	}

	if seen != len(exp.Events.Events) {
		t.Errorf("found %d events, want %d", seen, len(exp.Events.Events))
	}
}

// checkHealthVector walks the segment and checks each degraded-state bitmap,
// including that the reserved bit survives.
func checkHealthVector(t *testing.T, dir string, exp *vectorExpectation) {
	b, err := os.ReadFile(filepath.Join(dir, "segment.bin"))
	if err != nil {
		t.Fatalf("read segment.bin: %v", err)
	}

	res, err := ScanSegment(b, ScanState{}, vectorKeys(t))
	if err != nil {
		t.Fatalf("ScanSegment: %v", err)
	}

	var seen int
	for i := range res.Frames {
		f := &res.Frames[i]
		if f.RecordType != RecordDeviceHealth {
			continue
		}
		if seen >= len(exp.Health.Records) {
			t.Fatalf("segment holds more health records than the expectation names")
		}
		want := exp.Health.Records[seen]
		seen++

		h, err := ParseDeviceHealth(f.Payload)
		if err != nil {
			t.Errorf("health record %d does not parse: %v", seen-1, err)
			continue
		}

		if h.HealthState != want.HealthState {
			t.Errorf("health record %d state = %#02x, want %#02x", seen-1,
				h.HealthState, want.HealthState)
		}

		names := HealthStateNames(h.HealthState)
		if len(names) != len(want.Names) {
			t.Errorf("health record %d named %v, want %v", seen-1, names, want.Names)
			continue
		}
		for j := range names {
			if names[j] != want.Names[j] {
				t.Errorf("health record %d name %d = %q, want %q", seen-1, j,
					names[j], want.Names[j])
			}
		}
	}

	if seen != len(exp.Health.Records) {
		t.Errorf("found %d health records, want %d", seen, len(exp.Health.Records))
	}
}

func checkOBDExtVector(t *testing.T, dir string, exp *vectorExpectation) {
	t.Helper()

	b, err := os.ReadFile(filepath.Join(dir, "segment.bin"))
	if err != nil {
		t.Fatalf("read segment.bin: %v", err)
	}

	res, err := ScanSegment(b, ScanState{}, vectorKeys(t))
	if err != nil {
		t.Fatalf("ScanSegment: %v", err)
	}

	var seen int
	for i := range res.Frames {
		f := &res.Frames[i]
		if f.RecordType != RecordOBDExtended {
			continue
		}
		if seen >= len(exp.OBDExt.Records) {
			t.Fatalf("segment holds more OBD_EXTENDED records than expected")
		}
		want := exp.OBDExt.Records[seen]
		seen++

		o, err := ParseOBDExtended(f.Payload)
		if err != nil {
			t.Errorf("record %d does not parse: %v", seen-1, err)
			continue
		}

		checkPtrU16(t, seen-1, "map_kpa", o.MAPkPa, want.MAPkPa)
		checkPtrU16(t, seen-1, "maf_cgps", o.MAFcgps, want.MAFcgps)
		checkPtrU16(t, seen-1, "lambda_e4", o.LambdaE4, want.LambdaE4)
		checkPtrU16(t, seen-1, "abs_load_raw", o.AbsLoadRaw, want.AbsLoadRaw)
		checkPtrU8(t, seen-1, "baro_kpa", o.BaroKPa, want.BaroKPa)
		checkPtrI8(t, seen-1, "ambient_temp_c", o.AmbientTempC, want.AmbientTempC)
		checkPtrI8(t, seen-1, "fuel_trim_short_pct", o.FuelTrimShortPct, want.FuelTrimShortPct)
		checkPtrI8(t, seen-1, "fuel_trim_long_pct", o.FuelTrimLongPct, want.FuelTrimLongPct)

		if o.PIDsRequested != want.PIDsRequested {
			t.Errorf("record %d pids_requested = %d, want %d", seen-1, o.PIDsRequested, want.PIDsRequested)
		}
		if o.PIDsAnswered != want.PIDsAnswered {
			t.Errorf("record %d pids_answered = %d, want %d", seen-1, o.PIDsAnswered, want.PIDsAnswered)
		}
		if o.PollCadenceMS != want.PollCadenceMS {
			t.Errorf("record %d poll_cadence_ms = %d, want %d", seen-1, o.PollCadenceMS, want.PollCadenceMS)
		}

		if o.MAPSaturated() != want.MAPSaturated {
			t.Errorf("record %d MAPSaturated() = %v, want %v", seen-1, o.MAPSaturated(), want.MAPSaturated)
		}

		if want.BoostPSI != nil {
			got, ok := o.BoostPSI()
			if !ok {
				t.Errorf("record %d BoostPSI() unavailable, want %.2f", seen-1, *want.BoostPSI)
			} else if abs(got-*want.BoostPSI) > 0.01 {
				t.Errorf("record %d BoostPSI() = %.4f, want %.4f", seen-1, got, *want.BoostPSI)
			}
		} else {
			if _, ok := o.BoostPSI(); ok {
				t.Errorf("record %d BoostPSI() should be unavailable", seen-1)
			}
		}

		if want.Lambda != nil {
			got, ok := o.Lambda()
			if !ok {
				t.Errorf("record %d Lambda() unavailable, want %.4f", seen-1, *want.Lambda)
			} else if abs(got-*want.Lambda) > 0.0001 {
				t.Errorf("record %d Lambda() = %.6f, want %.6f", seen-1, got, *want.Lambda)
			}
		} else {
			if _, ok := o.Lambda(); ok {
				t.Errorf("record %d Lambda() should be unavailable", seen-1)
			}
		}

		if want.AbsLoadPct != nil {
			got, ok := o.AbsoluteLoadPct()
			if !ok {
				t.Errorf("record %d AbsoluteLoadPct() unavailable, want %.2f", seen-1, *want.AbsLoadPct)
			} else if abs(got-*want.AbsLoadPct) > 0.01 {
				t.Errorf("record %d AbsoluteLoadPct() = %.4f, want %.4f", seen-1, got, *want.AbsLoadPct)
			}
		} else {
			if _, ok := o.AbsoluteLoadPct(); ok {
				t.Errorf("record %d AbsoluteLoadPct() should be unavailable", seen-1)
			}
		}
	}

	if seen != len(exp.OBDExt.Records) {
		t.Errorf("found %d OBD_EXTENDED records, want %d", seen, len(exp.OBDExt.Records))
	}
}

func checkPtrU16(t *testing.T, idx int, name string, got, want *uint16) {
	t.Helper()
	if want == nil {
		if got != nil {
			t.Errorf("record %d %s = %d, want absent", idx, name, *got)
		}
		return
	}
	if got == nil {
		t.Errorf("record %d %s absent, want %d", idx, name, *want)
		return
	}
	if *got != *want {
		t.Errorf("record %d %s = %d, want %d", idx, name, *got, *want)
	}
}

